def set_left_most_unset_bit(n: int) -> int:
    if n < 0:
        raise ValueError("Input must be a non-negative integer")
    if n == 0:
        return 1  # leftmost unset bit is bit 0

    bit_length = n.bit_length()
    all_set_mask = (1 << bit_length) - 1
    if n == all_set_mask:
        # all bits set, leave unchanged
        return n

    # Find leftmost unset bit by checking bits from the highest position down to 0
    for i in reversed(range(bit_length)):
        if (n & (1 << i)) == 0:
            return n | (1 << i)

    # If no unset bit found in current bit length (should not happen due to check above)
